# Gumroad Integration for Selling Courses
import requests

GUMROAD_ACCESS_TOKEN = "PLxsE19GnjC5Nv1CbeKOiS5YqGqw35aZFJ"

def create_course_product(name, price, description):
    """Create a course product on Gumroad"""
    response = requests.post(
        "https://api.gumroad.com/v2/products",
        data={
            "access_token": GUMROAD_ACCESS_TOKEN,
            "name": name,
            "price": price,
            "description": description,
            "custom_permalink": name.lower().replace(" ", "-")
        }
    )
    return response.json()

def get_sales():
    """Get course sales data"""
    response = requests.get(
        "https://api.gumroad.com/v2/sales",
        params={"access_token": GUMROAD_ACCESS_TOKEN}
    )
    return response.json()
